import { Check, FileText, LoaderCircle } from "lucide-react";
import { cx, type WaitStateProps } from "./types";

export type FileStage = "uploading" | "reading" | "chunking" | "ready";
export type FileProcessingProps = WaitStateProps & { filename: string; size: string; stage?: FileStage; progress?: number };

const stages: Array<{ key: FileStage; label: string }> = [
  { key: "uploading", label: "Upload" },
  { key: "reading", label: "Reading" },
  { key: "chunking", label: "Chunking" },
  { key: "ready", label: "Ready" },
];

export function FileProcessing({ className, accent = false, filename, size, stage = "uploading", progress = 0 }: FileProcessingProps) {
  const activeIndex = stages.findIndex((item) => item.key === stage);
  const percent = stage === "ready" ? 100 : Math.max(0, Math.min(100, progress));
  return (
    <div className={cx("w-full max-w-md rounded-sm border border-border bg-background p-4 text-foreground", className)} aria-live="polite">
      <div className="flex items-center gap-3"><span className={cx("grid size-9 shrink-0 place-items-center rounded-lg bg-muted text-muted-foreground", accent && "text-primary")} aria-hidden="true"><FileText className="size-4" /></span><div className="min-w-0 flex-1"><p className="m-0 truncate text-sm font-medium">{filename}</p><p className="m-0 text-xs text-muted-foreground">{size}</p></div><span className="text-xs text-muted-foreground">{percent}%</span></div>
      <div className="my-3 h-1.5 overflow-hidden rounded-full bg-muted" aria-hidden="true"><span className={cx("block h-full rounded-full bg-muted-foreground transition-[width] motion-reduce:transition-none", accent && "bg-primary")} style={{ width: `${percent}%` }} /></div>
      <ol className="grid grid-cols-4 gap-1 text-center text-[10px] text-muted-foreground">
        {stages.map((item, index) => <li key={item.key} className={cx("flex min-w-0 flex-col items-center gap-1", index === activeIndex && "text-foreground")}><span className={cx("grid size-5 place-items-center rounded-full border border-border", index === activeIndex && accent && "border-primary text-primary")} aria-hidden="true">{index < activeIndex || stage === "ready" ? <Check className="size-3" /> : index === activeIndex ? <LoaderCircle className="size-3 motion-safe:animate-spin" /> : null}</span><span className="truncate">{item.label}</span></li>)}
      </ol>
    </div>
  );
}

export type AgentStatus =
  | "thinking"
  | "reasoning"
  | "sources"
  | "tool"
  | "plan"
  | "approval"
  | "queue"
  | "file"
  | "streaming"
  | "stalled"
  | "error"
  | "done";

export type AgentSource = {
  id?: string;
  url?: string;
  domain?: string;
  title: string;
};

export type AgentStatusSnapshot = {
  state: AgentStatus;
  activeToolName?: string;
  reasoning?: string;
  sources: AgentSource[];
  elapsedMs: number;
  showCancel: boolean;
  label: string;
  cancel?: () => void;
};

export type WaitStateProps = {
  className?: string;
  accent?: boolean;
};

export function cx(...values: Array<string | false | null | undefined>) {
  return values.filter(Boolean).join(" ");
}
